import{_ as i,l,o as e,c as E,v as t,p as s,x as r,d as n,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"LER 转移与平滑","description":"","frontmatter":{"title":"LER 转移与平滑","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/ler-transfer-smoothing.md","filePath":"litho/ler-transfer-smoothing.md","lastUpdated":1789023840000}'),p={name:"litho/ler-transfer-smoothing.md"};function A(c,a,D,_,m,S){const o=l("Mermaid");return e(),E("div",null,[a[1]||(a[1]=t('<h1 id="ler-转移与平滑" tabindex="-1">LER 转移与平滑 <a class="header-anchor" href="#ler-转移与平滑" aria-label="Permalink to &quot;LER 转移与平滑&quot;">​</a></h1><div class="epigraph"><p>显影边的粗糙不会原样刻进硅：等离子体可以抹高频、放大低频，或把相关长度改写成器件看见的那一截。</p><footer>—— 对照 LER/LWR 转移、刻蚀平滑与 PSD 的公开讨论；[LER 的 PSD](/litho/ler-psd) 已钉频谱</footer></div><p><a href="/litho/selectivity-arde">上一课</a>把过刻写成选择比的税。缺口是边的频谱：ADI 的 LER 不是 AEI 的 LER。<a href="/litho/ler-psd">LER PSD</a> 与 <a href="/litho/ler-correlation-length">相关长度</a> 已在胶侧讲过；本课钉转印算子对频谱做什么，不重推 3σ 定义。硬掩模材料如何当「更耐打的边」，留给[下一课](/litho/hardmask-sin-tin）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>离子轰击与侧壁聚合物可以平滑高频粗糙（小突起先被打掉或填平），低频弯曲（来自光学或长程负荷）往往留下甚至因负载放大。器件关心的相关长度通常在栅长量级：<a href="/litho/ler-device-impact">器件影响课</a> 已说明；转印若把低频留下、高频抹掉，3σ 下降却电学不变——报表会骗人。</p><p>缺口是<strong>转移函数</strong>，不是再测一次 ADI LER。把「刻蚀平滑 20%」写进预算而不声明频段，是类别错误。</p><h3 id="平滑不是免费的" tabindex="-1">平滑不是免费的 <a class="header-anchor" href="#平滑不是免费的" aria-label="Permalink to &quot;平滑不是免费的&quot;">​</a></h3><p>能抹粗糙的工艺往往也抹小 jog、小 SRAF 残和尖角，或引入斜侧壁。过度平滑与 CD 放宽、选择比损失捆绑。EUV 随机的高频成分可被部分抹平，但缺孔/桥连是拓扑事件，平滑救不回。</p><p><span class="marginnote">比较 ADI/AEI LER 必须同一部位、同一 SEM 算法。收缩与滤波差会假装平滑。PSD 比单点 3σ 更难作假。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>成对 ADI/AEI SEM，算 PSD 比而不是只报 3σ。工艺旋钮：离子能量、聚合物、过刻、后续修整（含 ALE）。与 OPC：若 AEI 低频 LER 来自光学，应改光源/OPC 而不是指望腔体。与随机窗：拓扑缺陷计数仍用缺陷检测，不把 LER 下降当随机良率。</p><p>硬掩模转印多一跳，每跳一个转移函数，总 PSD 是级联。</p><p>报告 AEI LER 时声明：空间频率窗、SEM 滤波、以及对应的器件相关长度。只报「刻蚀后 3σ 降了」而不给 PSD 比，器件课无法使用。公开的 LER 转移讨论都把频段写进方法，本课把这句话收成计量合同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>高频：曲率大，离子角与表面扩散优先削峰。低频：对应开口宽度调制，负荷与 ARDE 把它变成速率调制，可能放大。相关长度在转印后常变长，3σ 降、电学有效 LER 不一定降。侧壁角把顶视 SEM 的「边」定义改变，表观平滑可能是投影效应。</p>',15)),(e(),s(d,null,{default:r(()=>[h(o,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADI%5B%22ADI%20PSD%22%5D%20--%3E%20ET%5B%22%E5%88%BB%E8%9A%80%E8%BD%AC%E7%A7%BB%22%5D%0A%20%20ET%20--%3E%20HI%5B%22%E9%AB%98%E9%A2%91%E8%A1%B0%E5%87%8F%22%5D%0A%20%20ET%20--%3E%20LO%5B%22%E4%BD%8E%E9%A2%91%E6%AE%8B%E7%95%99%E6%88%96%E6%94%BE%E5%A4%A7%22%5D%0A%20%20HI%20--%3E%20AEI%5B%22AEI%20PSD%22%5D%0A%20%20LO%20--%3E%20AEI%0A%20%20AEI%20--%3E%20DEV%5B%22%E5%99%A8%E4%BB%B6%E7%9B%B8%E5%85%B3%E9%95%BF%E5%BA%A6%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把某食谱的平滑百分比当宇宙常数。不重写胶化学随机。本课不谈限价簿。</p><p>后课默认：预算要用 AEI PSD 的频段，并对着器件相关长度。下一课引入 SiN/TiN 硬掩模，把胶的薄与粗糙从深度预算里拆出去。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>刻蚀对 LER 是带通/低通算子，必须看 PSD 而不是只看 3σ。</li><li>高频可抹，低频与拓扑缺陷不能靠平滑报销。</li><li>多级硬掩模是级联转移。</li><li>出处：LER 转移与刻蚀平滑公开讨论；Mack / 计量对 PSD 的用法。</li></ul>',5))])}const P=i(p,[["render",A]]);export{B as __pageData,P as default};
